# -*- coding: utf-8 -*-
# Insert config_audit_reconcile between config_history_replay and config_cas.

with open("/home/c/brix3/a/task052/access.py", "r", encoding="utf-8") as f:
    lines = f.readlines()

# Locate boundaries programmatically.
replay_idx = None
cas_idx = None
for i, line in enumerate(lines):
    if line.startswith("    def config_history_replay"):
        replay_idx = i
    if line.startswith("    def config_cas"):
        cas_idx = i
        break
assert replay_idx is not None and cas_idx is not None
# Blank line immediately precedes config_cas.
assert lines[cas_idx - 1] == "\n", repr(lines[cas_idx - 1])

method = '''    def config_audit_reconcile(self):
        """只读对账在册配置历史与全量防篡改 audit 链，返回 LF 尾紧凑 JSON；
        不老化、不改任何状态，首错即停、返回失败而不抛异常。

        修订来源仅“构造/直接/事务”：修订 0 为构造；非经 config_change 的
        提交（直载/直滚/CAS/回退）为直接；config_change 首次加载/回滚成功
        为事务，并在 audit 链记原序号 0 的首次事件；失败、升级、重放不产生
        修订。

        校验次序固定：
        一、先按 config_history_replay 规则（见 _config_history_scan）全量
        校验并演算在册配置历史；任一首次出错即归“历史”，断点取该修订
        （修订号不可读取 -1）、断点审计 -1（审计尚未校验）。
        二、再自空哈希（64 个 0）起校验全量 audit 链：序号自 1 连续、前哈希
        衔接前项（首项衔接 64 个 0）、哈希可由前八字段重算；任一首次出错即
        归“审计”，断点修订 -1、断点审计取该事件序号（不可读取 -1）。
        三、最后按修订升序验来源：构造与直接项无关联；事务项（加载/回滚）
        须唯一关联一个操作“配置加载/配置回滚”、结果“成功”、原序号 0 的
        首次事件——以事件键在 config_change 重放缓存中的首果配置摘要定位
        唯一在册修订（同摘要的先后次序按提交序对齐，已淘汰修订为可信边界、
        不要求关联），并核对缓存操作映射的链操作与历史操作一致（违例归
        “操作”）、首果为成功（违例归“结果”）、事件键/时刻取原调用（时刻须
        等于缓存首调时刻、会话为空串，违例归“关联”）；配对事件序号须随修订
        升序单调（违例归“来源”）。修订无配对事件即为直接来源，合法。
        链级复核（不关联修订，断点修订取 -1、断点审计取事件序号）：同一键
        的 config_change 域原序号 0 事件至多一个（重复归“来源”）；原序号
        非 0 的重放事件须指向同键同操作、原序号 0 的首次事件，结果须为
        “重放成功”或“重放”加首果名（违例归“重放”）。配置升级及其余域
        事件不关联修订。

        淘汰修订（配置历史仅留最近 256 项，audit 链全量不淘汰）为可信
        边界：仅对账在册修订，对应已淘汰修订的首次事件不要求关联。检查仅
        计通过修订（可信锚不计）；成功时两断点均 -1、原因为空串，末修订取
        当前修订、末审计取末事件序号（空链为 0）；失败时末修订/末审计取
        已验到的位置。顶层键序/型为“锚修订:int、检查:int、完整:bool、
        断点修订:int、断点审计:int、原因:str、末修订:int、末审计:int”，
        原因仅取“历史/审计/来源/关联/操作/结果/重放”，不可读断点为 -1。
        时间 O(A+H·C)、辅助空间 O(H)，A 为审计事件数、H 为在册修订数、
        C 为单份配置编码成本。
        """
        scan = self._config_history_scan()
        anchor_revision = scan["anchor_revision"]
        checked = scan["checked"]

        def failed(bp_revision, bp_audit, reason, last_revision, last_audit):
            payload = {
                "锚修订": anchor_revision,
                "检查": checked,
                "完整": False,
                "断点修订": bp_revision,
                "断点审计": bp_audit,
                "原因": reason,
                "末修订": last_revision,
                "末审计": last_audit,
            }
            return (
                json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
                + "\\n"
            )

        # 一、配置历史（含提交语义演算）；审计链尚未校验，末审计取 0。
        if not scan["complete"]:
            bp_revision, _hist_reason = scan["broken"]
            return failed(
                bp_revision, -1, "历史",
                scan["last_revision"], 0,
            )

        log = self._config_history_log
        last_revision = log[-1][0]
        chain = self._chain_events
        config_ops = (
            _CONFIG_CHAIN_LOAD,
            _CONFIG_CHAIN_ROLLBACK,
            _CONFIG_CHAIN_UPGRADE,
        )
        load_rollback_chain_ops = (
            _CONFIG_CHAIN_LOAD,
            _CONFIG_CHAIN_ROLLBACK,
        )

        # 二、全量 audit 链：连续序号、前哈希衔接、哈希重算。
        prev_hash = "0" * 64
        last_audit = 0
        for expect, event in enumerate(chain, start=1):
            (seq, ev_now, key, op, sid, result, origin,
             stored_prev, digest) = event
            seq_ok = (
                isinstance(seq, int)
                and not isinstance(seq, bool)
                and seq == expect
            )
            bp_audit = seq if seq_ok else -1
            if not seq_ok or stored_prev != prev_hash:
                return failed(-1, bp_audit, "审计", last_revision, last_audit)
            recomputed = None
            try:
                recomputed = self._chain_hash(
                    seq, ev_now, key, op, sid, result, origin, stored_prev
                )
            except Exception:
                recomputed = None
            if recomputed is None or digest != recomputed:
                return failed(-1, bp_audit, "审计", last_revision, last_audit)
            prev_hash = digest
            last_audit = seq
        total_audit = len(chain)

        # 三、来源对账。为每个操作“配置加载/配置回滚”、原序号 0、结果
        # “成功”的首次事件，按其键在 config_change 缓存中的首果配置摘要
        # 打标（缓存缺失或首果非成功则无摘要，不参与配对）；摘要定位唯一
        # 在册修订，重放缓存不老化、audit 链亦不截断，故事件与缓存同寿。
        tagged = []
        for event in chain:
            seq, ev_now, key, op, sid, result, origin = event[:7]
            if (
                op not in load_rollback_chain_ops
                or origin != 0
                or result != "成功"
            ):
                continue
            cache = self._config_change_cache.get(key)
            config_digest = None
            if cache is not None and cache[3][0] == "ok":
                try:
                    config_digest = hashlib.sha256(
                        cache[3][1][:-1].encode("utf-8")
                    ).hexdigest()
                except Exception:
                    config_digest = None
            tagged.append((seq, event, cache, config_digest))

