    原因仅取“历史/审计/来源/关联/操作/结果/重放”，不可读断点为 -1。
    时间 O(A+H·C)、辅助空间 O(H)，A 为审计事件数、H 为在册修订数、
    C 为单份配置编码成本。
    """
    scan = self._config_history_scan()
    anchor_revision = scan["anchor_revision"]
    checked = scan["checked"]

    def failed(bp_revision, bp_audit, reason, last_revision, last_audit):
        payload = {
            "锚修订": anchor_revision,
            "检查": checked,
            "完整": False,
            "断点修订": bp_revision,
            "断点审计": bp_audit,
            "原因": reason,
            "末修订": last_revision,
            "末审计": last_audit,
        }
        return (
            json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
            + "\n"
        )

    # 一、配置历史（含提交语义演算）；审计链尚未校验，末审计取 0。
    if not scan["complete"]:
        bp_revision, _hist_reason = scan["broken"]
        return failed(
            bp_revision, -1, "历史",
            scan["last_revision"], 0,
        )

    log = self._config_history_log
    last_revision = log[-1][0]
    chain = self._chain_events
    config_ops = (
        _CONFIG_CHAIN_LOAD,
        _CONFIG_CHAIN_ROLLBACK,
        _CONFIG_CHAIN_UPGRADE,
    )
    load_rollback_chain_ops = (
        _CONFIG_CHAIN_LOAD,
        _CONFIG_CHAIN_ROLLBACK,
    )

    # 二、全量 audit 链：连续序号、前哈希衔接、哈希重算。
    prev_hash = "0" * 64
    last_audit = 0
    for expect, event in enumerate(chain, start=1):
        (seq, ev_now, key, op, sid, result, origin,
         stored_prev, digest) = event
        seq_ok = (
            isinstance(seq, int)
            and not isinstance(seq, bool)
            and seq == expect
        )
        bp_audit = seq if seq_ok else -1
        if not seq_ok or stored_prev != prev_hash:
            return failed(-1, bp_audit, "审计", last_revision, last_audit)
        recomputed = None
        try:
            recomputed = self._chain_hash(
                seq, ev_now, key, op, sid, result, origin, stored_prev
            )
        except Exception:
            recomputed = None
        if recomputed is None or digest != recomputed:
            return failed(-1, bp_audit, "审计", last_revision, last_audit)
        prev_hash = digest
        last_audit = seq
    total_audit = len(chain)

    # 三、来源对账。为每个操作“配置加载/配置回滚”、原序号 0、结果
    # “成功”的首次事件，按其键在 config_change 缓存中的首果配置摘要
    # 打标（缓存缺失或首果非成功则无摘要，不参与配对）；摘要定位唯一
    # 在册修订，重放缓存不老化、audit 链亦不截断，故事件与缓存同寿。
    tagged = []
    for event in chain:
        seq, ev_now, key, op, sid, result, origin = event[:7]
        if (
            op not in load_rollback_chain_ops
            or origin != 0
            or result != "成功"
        ):
            continue
        cache = self._config_change_cache.get(key)
        config_digest = None
        if cache is not None and cache[3][0] == "ok":
            try:
                config_digest = hashlib.sha256(
                    cache[3][1][:-1].encode("utf-8")
                ).hexdigest()
            except Exception:
                config_digest = None
        tagged.append((seq, event, cache, config_digest))

    # 在册加载/回滚修订按摘要分组；同摘要组内按提交序对齐：已淘汰修订
    # 的事件必在链上更早位置，故事件多于修订时取最末的若干事件与在册
    # 修订配对，余下事件属可信边界；事件少于修订时余者为直接来源。
    records_by_digest = {}
    for record in log:
        if record[2] in (
            _CONFIG_HISTORY_OP_LOAD,
            _CONFIG_HISTORY_OP_ROLLBACK,
        ):
            records_by_digest.setdefault(record[4], []).append(record)
    paired = {}
    for config_digest, records in records_by_digest.items():
        events_match = sorted(
            (tag for tag in tagged if tag[3] == config_digest),
            key=lambda tag: tag[0],
        )
        take = min(len(records), len(events_match))
        for record, tag in zip(
            records[len(records) - take:],
            events_match[len(events_match) - take:],
        ):
            paired[record[0]] = tag

    # 按修订升序验事务项：无配对事件的加载/回滚项为直接来源，不关联。
    last_paired_seq = 0
    for record in log:
        revision, _parent, hist_op, _target, _summary, _ph, _h = record
        if hist_op not in (
            _CONFIG_HISTORY_OP_LOAD,
            _CONFIG_HISTORY_OP_ROLLBACK,
        ):
            continue
        tag = paired.get(revision)
        if tag is None:
            continue
        event_seq, event, cache, config_digest = tag
        ev_seq, ev_now, ev_key, ev_op, ev_sid, ev_result, ev_origin = event[:7]
        # 配对事件序号须随修订升序单调（记录先提交、事件后入链）。
        if event_seq < last_paired_seq:
            return failed(
                revision, event_seq, "来源", last_revision, total_audit
            )
        # 键取原调用：缓存须存在且首果可读，否则关联不可证。
        if cache is None or config_digest is None:
            return failed(
                revision, event_seq, "关联", last_revision, total_audit
            )
        c_op, _c_text, c_now_ms, outcome = cache
        # 操作匹配历史：缓存原调操作映射的链操作须等于事件操作且等于
        # 历史记录操作（加载↔配置加载、回滚↔配置回滚）。
        if _CONFIG_CHAIN_OP.get(c_op) != ev_op or c_op != hist_op:
            return failed(
                revision, event_seq, "操作", last_revision, total_audit
            )
        # 事务首事件首果须为成功。
        if outcome[0] != "ok" or ev_result != "成功" or ev_origin != 0:
            return failed(
                revision, event_seq, "结果", last_revision, total_audit
            )
        # 键、时刻取原调用：事件键即缓存键（查表同源），时刻须等于
        # 首调时刻；config_change 事件会话恒为空串。
        if ev_now != c_now_ms or ev_sid != "":
            return failed(
                revision, event_seq, "关联", last_revision, total_audit
            )
        last_paired_seq = event_seq

    # 链级复核（按事件序号升序，不关联修订）：config_change 域首次事件
    # 同键唯一；重放事件须指向同键同操作的首次事件且首果名对应。
    first_seq_by_key = {}
    for event in chain:
        seq, ev_now, key, op, sid, result, origin = event[:7]
        if op not in config_ops:
            continue
        if origin == 0:
            if key in first_seq_by_key:
                # 同键第二次原序号 0：首次事件不唯一。
                return failed(
                    -1, seq, "来源", last_revision, total_audit
                )
            first_seq_by_key[key] = seq
            if result.startswith("重放"):
                # 原序号 0 的事件不得自报重放结果。
                return failed(
                    -1, seq, "重放", last_revision, total_audit
                )
        else:
            if not (1 <= origin <= total_audit):
                return failed(
                    -1, seq, "重放", last_revision, total_audit
                )
            target = chain[origin - 1]
            if target[6] != 0 or target[2] != key or target[3] != op:
                return failed(
                    -1, seq, "重放", last_revision, total_audit
                )
            expected_result = (
                "重放成功"
                if target[5] == "成功"
                else "重放" + target[5]
            )
            if result != expected_result:
                return failed(
                    -1, seq, "重放", last_revision, total_audit
                )

    payload = {
        "锚修订": anchor_revision,
        "检查": checked,
        "完整": True,
        "断点修订": -1,
        "断点审计": -1,
        "原因": "",
        "末修订": last_revision,
        "末审计": total_audit,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

