        break
    if origin != 0 or cindex.get(ev_key) != seq:
        continue
    cache = ccache.get(ev_key)
    if not isinstance(cache, tuple) or len(cache) != 4:
        continue
    c_op, _c_text, _c_now_ms, outcome = cache
    if (
        not isinstance(outcome, tuple)
        or len(outcome) != 2
        or c_op not in (_CONFIG_OP_LOAD, _CONFIG_OP_ROLLBACK)
        or outcome[0] != "ok"
        or not isinstance(outcome[1], str)
    ):
        continue
    try:
        config_digest = hashlib.sha256(
            outcome[1][:-1].encode("utf-8")
        ).hexdigest()
    except Exception:
        config_digest = None
    selected.append((seq, ev_key, cache, config_digest))
candidates = selected  # 链尾向前收集，配对前按组内序号重排。

# 在册加载/回滚修订按 (历史操作, 摘要) 分组：事务加载与事务回滚即使
# 产出同一配置摘要（回滚可重建早前加载态，CAS 之间尤甚）也不可互相
# 配对。同组内按首次事件序号对齐：候选已涵盖最后 H 个成功首调事件，
# 组内取最末的若干候选与在册修订一一配对；候选少于在册修订时余者为
