        "原因", "末修订", "末审计"]


def build(seed):
    rnd = random.Random(seed)
    auth = Authenticator(3, 1000); auth.add("alice", "pw"); auth.add("bob", "pw")
    s = Sessions(auth, 6, 3, 5000,
                 pool=("10.0.0.0/24", ("10.0.0.9",),
                       (("alice", "10.0.0.2"), ("bob", "10.0.0.3"))),
                 lease_ms=1000)
    doc = json.loads(s.export_config())
    for i in range(rnd.randint(1, 120)):
        doc["会话"]["租期毫秒"] = 1000 + i
        txt = json.dumps(doc, ensure_ascii=False)
        c = rnd.randrange(8)
        try:
            if c < 3:
                s.config_change(f"k{i}", "加载", txt, i)
                if rnd.random() < 0.25:
                    s.config_change(f"k{i}", "加载", txt, i)
            elif c < 4:
                s.load_config(txt)
            elif c < 5:
                rev = json.loads(s.config_revision())["修订"]
                s.config_cas(f"cas{i}", txt, rev, i)
            elif c < 6:
                rev = json.loads(s.config_revision())["修订"]
                if rev > 0:
                    try:
                        s.config_revert(f"rv{i}", rnd.randrange(rev), rev, i)
                    except KeyError:
                        pass
            elif c < 7:
                try:
                    s.config_change(f"rb{i}", "回滚", None, i)
                except StateError:
                    pass
            else:
                try:
                    s.config_change(f"u{i}", "升级", s.export_config(), i)
                except ValueError:
                    pass
        except (ValueError, ResourceError, StateError):
            pass
    return s


def mutate(s, rnd):
    kind = rnd.randrange(7)
    if kind == 0 and s._chain_events:
        i = rnd.randrange(len(s._chain_events))
        e = list(s._chain_events[i])
        f = rnd.randrange(len(e))
        e[f] = rnd.choice([1, "x", -3, None, True, 999, "成功"])
        s._chain_events[i] = tuple(e)
    elif kind == 1 and s._config_history_log:
        i = rnd.randrange(len(s._config_history_log))
        r = list(s._config_history_log[i])
        r[rnd.randrange(len(r))] = rnd.choice([1, "x", -3, None, "0" * 64])
        s._config_history_log[i] = tuple(r)
    elif kind == 2 and s._config_history:
        k = rnd.choice(list(s._config_history))
        if rnd.random() < 0.5:
            del s._config_history[k]
        else:
            spec = list(s._config_history[k])
            spec[0] = spec[0] + 1
            s._config_history[k] = tuple(spec)
    elif kind == 3 and s._config_change_cache:
        k = rnd.choice(list(s._config_change_cache))
        if rnd.random() < 0.4:
            del s._config_change_cache[k]
        else:
            c = list(s._config_change_cache[k])
            c[0] = rnd.choice(["加载", "回滚", "升级", 9])
            c[2] = rnd.randint(0, 9999)
            s._config_change_cache[k] = tuple(c)
    elif kind == 4 and s._config_change_chain_index:
        k = rnd.choice(list(s._config_change_chain_index))
        s._config_change_chain_index[k] = rnd.choice([0, 1, 999, -2, None])
    elif kind == 5:
        s._chain_events = [("z",) * 9] + s._chain_events
    else:
        s._revision = rnd.randint(0, 10000)


seen_reasons = set()
trials = 4000
for t in range(trials):
    s = build(t % 40)
    rnd = random.Random(t)
    mutate(s, rnd)
    try:
        out = s.config_audit_reconcile()
        o = json.loads(out)
        assert list(o) == KEYS, o
        assert o["原因"] in REASONS, o
        if o["完整"]:
            assert o["原因"] == "" and o["断点修订"] == -1 and o["断点审计"] == -1
        else:
            assert o["原因"]
        seen_reasons.add(o["原因"])
    except Exception as exc:
        print(f"RAISED on trial {t}: {type(exc).__name__}: {exc}")
        raise

print(f"tamper fuzz OK: {trials} trials; reasons seen: {sorted(seen_reasons)}")

